content.css:
/* ========================================================================== */
/* BFUSION Benefits Realization Tracker — Modern UI                          */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  box-sizing: border-box;
  font-family: var(--brt-font, "Segoe UI"), wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #242424;
  padding-bottom: 24px;
  /* license badge clear zone */
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Main Container + Body                                                      */
/* ========================================================================== */
.bfusion-brt-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* ========================================================================== */
/* Header                                                                     */
/* ========================================================================== */
.brt-header {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px 6px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-bottom: 1px solid #E5E7EB;
  flex-shrink: 0;
  min-height: 0;
}
.brt-header__titles {
  flex: 1;
  min-width: 0;
}
.brt-header__title {
  font-size: var(--brt-title-font, 14px);
  font-weight: 700;
  color: #242424;
  line-height: 1.2;
}
.brt-header__subtitle {
  font-size: var(--brt-subtitle-font, 11px);
  color: #6C757D;
  margin-top: 1px;
  line-height: 1.3;
}
.brt-info {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #FFFFFF;
  color: #6C757D;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  flex-shrink: 0;
}
.brt-info:hover {
  background: var(--brt-accent, #E8612A);
  color: #FFFFFF;
  border-color: var(--brt-accent, #E8612A);
}
.brt-info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  width: 320px;
  max-width: calc(100% - 24px);
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
  padding: 14px 16px 12px;
  z-index: 30;
  display: none;
  font-size: 11px;
  color: #242424;
}
.brt-info-pop--open {
  display: block;
}
.brt-info-pop__close {
  position: absolute;
  top: 4px;
  right: 6px;
  width: 22px;
  height: 22px;
  background: transparent;
  border: 0;
  color: #6C757D;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  border-radius: 4px;
}
.brt-info-pop__close:hover {
  background: #F8F9FB;
  color: #242424;
}
.brt-info-pop__title {
  font-size: 13px;
  font-weight: 700;
  padding-bottom: 6px;
  border-bottom: 2px solid var(--brt-accent, #E8612A);
  margin-bottom: 8px;
  padding-right: 20px;
}
.brt-info-pop__desc {
  font-size: 11px;
  color: #242424;
  line-height: 1.5;
  margin-bottom: 10px;
}
.brt-info-pop__how {
  font-size: 11px;
  font-weight: 600;
  color: #6C757D;
  margin-bottom: 4px;
  text-transform: none;
}
.brt-info-pop__bullets {
  list-style: disc;
  padding-left: 18px;
  margin: 0;
  font-size: 11px;
  color: #242424;
  line-height: 1.55;
}
.brt-info-pop__bullets li {
  margin-bottom: 3px;
}
.brt-info-pop__bullets li:last-child {
  margin-bottom: 0;
}
/* ========================================================================== */
/* Body Layout (chart + strip + insight panel)                                */
/* ========================================================================== */
.brt-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
  overflow: hidden;
}
.brt-chart {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: 10px 12px 12px;
  scrollbar-gutter: stable;
}
/* Visible, modern scrollbars (Power BI hides overlay scrollbars until hover) */
.brt-chart,
.brt-insight-panel {
  scrollbar-width: thin;
  scrollbar-color: #C3CAD6 transparent;
}
.brt-chart::-webkit-scrollbar,
.brt-insight-panel::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.brt-chart::-webkit-scrollbar-track,
.brt-insight-panel::-webkit-scrollbar-track {
  background: transparent;
}
.brt-chart::-webkit-scrollbar-thumb,
.brt-insight-panel::-webkit-scrollbar-thumb {
  background: #C3CAD6;
  border-radius: 4px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
.brt-chart::-webkit-scrollbar-thumb:hover,
.brt-insight-panel::-webkit-scrollbar-thumb:hover {
  background: #8E99AB;
  background-clip: padding-box;
}
.brt-insight-strip {
  width: 24px;
  flex-shrink: 0;
  background: #F8F9FB;
  border-left: 1px solid #E5E7EB;
  border-right: 1px solid #E5E7EB;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 0;
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;
}
.brt-insight-strip:hover {
  background: #fbe3d9;
}
.brt-insight-strip__arrow {
  color: var(--brt-accent, #E8612A);
  font-size: 11px;
  margin-bottom: 8px;
}
.brt-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #6C757D;
  text-transform: uppercase;
}
.brt-insight-panel {
  width: 260px;
  max-width: 320px;
  flex-shrink: 0;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  border-left: 1px solid #E5E7EB;
  overflow-y: auto;
  padding: 12px 14px 14px;
  font-size: var(--brt-insight-font, 12px);
  color: #242424;
}
.brt-body--insight-collapsed .brt-insight-panel {
  display: none;
}
.brt-body--insight-hidden .brt-insight-panel,
.brt-body--insight-hidden .brt-insight-strip {
  display: none;
}
/* ========================================================================== */
/* Rows                                                                       */
/* ========================================================================== */
.brt-row {
  margin-bottom: 12px;
}
.brt-row:last-child {
  margin-bottom: 0;
}
/* ========================================================================== */
/* KPI Cards (modernized: gradient accent, soft shadow, larger numerals)       */
/* ========================================================================== */
.brt-row--kpis {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.brt-kpi {
  flex: 1 1 120px;
  min-width: 110px;
  max-width: 220px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: row;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
.brt-kpi:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}
.brt-kpi__accent {
  width: 4px;
  flex-shrink: 0;
}
.brt-kpi__body {
  padding: 10px 14px;
  flex: 1;
  min-width: 0;
}
.brt-kpi__value {
  font-size: var(--brt-kpi-value-font, 22px);
  font-weight: 700;
  line-height: 1.15;
  margin-bottom: 2px;
  letter-spacing: -0.3px;
}
.brt-kpi__label {
  font-size: var(--brt-kpi-label-font, 10px);
  font-weight: 600;
  color: #6C757D;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.brt-kpi__sub {
  font-size: calc(var(--brt-kpi-label-font, 10px) - 1px);
  color: #8b949b;
  margin-top: 2px;
}
/* ========================================================================== */
/* Gauge                                                                      */
/* ========================================================================== */
.brt-gauge {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 10px;
  padding: 12px 16px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
.brt-gauge__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}
.brt-gauge__title {
  font-size: var(--brt-section-title-font, 11px);
  font-weight: 700;
  color: #6C757D;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.brt-gauge__pct {
  font-size: var(--brt-gauge-pct-font, 22px);
  font-weight: 700;
  letter-spacing: -0.3px;
}
.brt-gauge__pct-sub {
  font-size: 11px;
  font-weight: 600;
  color: #6C757D;
  letter-spacing: 0;
}
.brt-gauge__track {
  height: 14px;
  border-radius: 7px;
  background: #F8F9FB;
  overflow: hidden;
  margin-bottom: 6px;
  border: 1px solid #E5E7EB;
  position: relative;
}
.brt-gauge__fill {
  height: 100%;
  border-radius: 7px;
  transition: width 0.4s ease;
}
.brt-gauge__tick {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(31, 42, 68, 0.35);
  cursor: help;
}
.brt-gauge__labels {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #6C757D;
}
.brt-gauge__labels b {
  font-weight: 700;
  color: #242424;
}
/* ========================================================================== */
/* Projects List                                                              */
/* ========================================================================== */
.brt-projects {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 10px;
  padding: 0 14px 12px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
.brt-projects__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 12px;
  position: sticky;
  top: 0;
  z-index: 2;
  background: #FFFFFF;
  margin: 0 -14px 10px;
  padding: 12px 14px 8px;
  border-radius: 10px 10px 0 0;
  border-bottom: 1px solid #E5E7EB;
}
.brt-projects__title {
  font-size: var(--brt-section-title-font, 11px);
  font-weight: 700;
  color: #6C757D;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.brt-projects__legend {
  display: flex;
  gap: 12px;
}
.brt-legend {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  color: #6C757D;
  font-weight: 500;
}
.brt-legend__bar {
  width: 18px;
  height: 6px;
  border-radius: 3px;
  flex-shrink: 0;
}
.brt-legend__pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 14px;
  padding: 0 4px;
  border-radius: 999px;
  background: #F8F9FB;
  border: 1px solid #E5E7EB;
  font-size: 9px;
  font-weight: 700;
  color: #242424;
  flex-shrink: 0;
}
.brt-project {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #FFFFFF;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px 10px;
  margin-bottom: 4px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.brt-project:hover {
  background: #F8F9FB;
  border-color: #E5E7EB;
}
.brt-project:last-child {
  margin-bottom: 0;
}
.brt-project__info {
  flex: 0 0 170px;
  min-width: 130px;
}
.brt-project__name {
  font-size: var(--brt-project-name-font, 12px);
  font-weight: 600;
  color: #242424;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brt-project__meta {
  font-size: var(--brt-project-meta-font, 10px);
  color: #6C757D;
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brt-project__bars {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.brt-bar {
  display: flex;
  align-items: center;
  gap: 8px;
}
.brt-bar__track {
  flex: 1;
  height: 12px;
  border-radius: 6px;
  background: #F8F9FB;
  overflow: hidden;
  border: 1px solid #E5E7EB;
  position: relative;
}
.brt-bar__plan {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 6px;
}
.brt-bar__fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 6px;
  transition: width 0.3s ease;
}
.brt-bar__value {
  font-size: var(--brt-bar-value-font, 10px);
  font-weight: 600;
  color: #6C757D;
  flex-shrink: 0;
  min-width: 80px;
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.brt-bar__value-real {
  font-weight: 700;
}
.brt-bar__value-sep {
  color: #6C757D;
  font-weight: 500;
}
.brt-project__rate {
  flex-shrink: 0;
  font-size: var(--brt-rate-font, 16px);
  font-weight: 700;
  min-width: 52px;
  text-align: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
  line-height: 1.3;
  cursor: help;
}
.brt-project__cbr {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  min-width: 52px;
  text-align: center;
  padding: 2px 7px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
  cursor: help;
}
/* ========================================================================== */
/* Insight Panel — header, mini-KPI tiles, health-bar, smart insights, lists  */
/* ========================================================================== */
.brt-insight-panel__header {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--brt-accent, #E8612A);
}
.brt-insight-panel__title {
  font-size: var(--brt-insight-header-font, 13px);
  font-weight: 700;
  color: #242424;
  line-height: 1.2;
}
.brt-insight-panel__sub {
  font-size: 10px;
  color: #6C757D;
  margin-top: 2px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.brt-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 12px;
}
.brt-mkpi {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-left: 3px solid #6C757D;
  border-radius: 6px;
  padding: 6px 8px;
}
.brt-mkpi__value {
  font-size: calc(var(--brt-insight-font, 12px) + 4px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.2px;
}
.brt-mkpi__label {
  font-size: calc(var(--brt-insight-font, 12px) - 2px);
  color: #6C757D;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  margin-top: 2px;
}
.brt-health {
  margin-bottom: 12px;
}
.brt-health__bar {
  display: flex;
  height: 10px;
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid #E5E7EB;
  background: #F8F9FB;
}
.brt-health__seg {
  height: 100%;
  transition: width 0.3s ease;
}
.brt-health__legend {
  display: flex;
  justify-content: space-between;
  gap: 4px;
  margin-top: 4px;
  font-size: calc(var(--brt-insight-font, 12px) - 2px);
  color: #6C757D;
}
.brt-health__legend span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.brt-health__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.brt-smart {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  font-size: var(--brt-insight-font, 12px);
  line-height: 1.5;
  color: #242424;
}
.brt-smart li {
  position: relative;
  padding: 6px 8px 6px 18px;
  border-radius: 6px;
  margin-bottom: 4px;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
}
.brt-smart li:before {
  content: "›";
  position: absolute;
  left: 6px;
  top: 5px;
  color: var(--brt-accent, #E8612A);
  font-weight: 700;
}
.brt-smart b {
  font-weight: 700;
}
.brt-insight-list {
  margin-bottom: 10px;
}
.brt-insight-list__title {
  font-size: calc(var(--brt-insight-font, 12px) - 1px);
  font-weight: 700;
  color: #6C757D;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 4px;
}
.brt-insight-row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  font-size: var(--brt-insight-font, 12px);
}
.brt-insight-row__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}
.brt-insight-row__name {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #242424;
}
.brt-insight-row__val {
  font-weight: 700;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
/* ========================================================================== */
/* Responsive                                                                 */
/* ========================================================================== */
.brt-root.brt-medium .brt-insight-panel {
  width: 210px;
}
.brt-root.brt-medium .brt-project__info {
  flex-basis: 140px;
}
.brt-root.brt-medium .brt-kpi {
  min-width: 100px;
}
.brt-root.brt-medium .brt-kpi__sub {
  display: none;
}
.brt-root.brt-narrow {
  /* Stack each project row: name line on top, bar + pills below */
}
.brt-root.brt-narrow .brt-body {
  flex-direction: row;
}
.brt-root.brt-narrow .brt-insight-panel {
  position: absolute;
  right: 24px;
  top: 0;
  bottom: 24px;
  z-index: 25;
  width: 240px;
  box-shadow: -4px 0 12px rgba(0, 0, 0, 0.08);
}
.brt-root.brt-narrow .brt-body--insight-collapsed .brt-insight-panel {
  display: none;
}
.brt-root.brt-narrow .brt-row--kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.brt-root.brt-narrow .brt-kpi {
  max-width: none;
  min-width: 0;
}
.brt-root.brt-narrow .brt-kpi__sub {
  display: none;
}
.brt-root.brt-narrow .brt-kpi__value {
  font-size: calc(var(--brt-kpi-value-font, 22px) - 4px);
}
.brt-root.brt-narrow .brt-project {
  flex-wrap: wrap;
  row-gap: 4px;
  padding: 8px;
}
.brt-root.brt-narrow .brt-project__info {
  flex: 1 1 100%;
  min-width: 0;
}
.brt-root.brt-narrow .brt-project__bars {
  flex: 1 1 120px;
}
.brt-root.brt-narrow .brt-bar__value {
  min-width: 0;
}
.brt-root.brt-narrow .brt-project__rate {
  font-size: calc(var(--brt-rate-font, 16px) - 3px);
  min-width: 44px;
}
.brt-root.brt-narrow .brt-project__cbr {
  min-width: 44px;
}
.brt-root.brt-narrow .brt-projects__legend .brt-legend:nth-child(n+3) {
  display: none;
}
/* ========================================================================== */
/* Landing Page                                                               */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  color: #666;
  line-height: 1.5;
  margin: 0;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
}
/* ========================================================================== */
/* Empty data state                                                            */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
